3	//! minix.rs VFS (virtual file system) server — skeletal boot (slice 4.2), plus the
4	//! slice-5.2 grant demo and the slice-5.3 console demo.
5	//!
6	//! Slice 4.2 stood VFS up as a real boot server: it boots through the SEF
7	//! framework and publishes its endpoint to DS, proving the multi-server boot
8	//! path and the DS registry end to end. It does *no* file operations yet — the
9	//! PM↔VFS fork/exec work protocol needs file descriptors and is Phase 5 — so the
10	//! receive loop simply drops any application traffic that arrives.
11	//!
12	//! Slice 5.2 gives VFS the granting half of the first real cross-address-space
13	//! copy: it direct-grants a checksummed read-only buffer to PM and hands PM the
14	//! grant id in a `PM_GRANT_TEST` message. See [`grant_test`].
15	//!
16	//! Slice 5.3 makes VFS the first client of the TTY console driver: it looks TTY up
17	//! in DS and drives `CDEV_WRITE` — a real write, a short write, and two refusals.
18	//! See [`tty_demo`]. That is not throwaway wiring: slice 5.4 puts VFS's fd 1 and 2
19	//! on this exact path.
20	//!
21	//! Built as a freestanding aarch64 ELF (see `servers/vfs/user.ld`), packed into
22	//! the kernel's boot-image archive by `kernel/build.rs`, and loaded into its own
23	//! per-process AddrSpace at boot by `arch::aarch64::userland::load_boot_server`.
24	
25	// Freestanding for the real (bare-metal) build, but a normal host binary under
26	// `cargo test` (no host tests yet — the SEF/IPC glue is QEMU-verified). The
27	// `_start` shim and panic handler are gated to `not(test)`.
28	#![cfg_attr(not(test), no_std)]
29	#![cfg_attr(not(test), no_main)]
30	
31	minixrs_abi_note::brand!();
32	
33	use minixrs_ipc::{ipc_send, ipc_sendrec};
34	use minixrs_kernel_shared::Message;
35	use minixrs_kernel_shared::callnr::{
36	    CDEV_GRANT_OFF, CDEV_LEN_OFF, CDEV_MAX_IO, CDEV_MINOR_CONSOLE, CDEV_MINOR_OFF, CDEV_OFFSET_OFF,
37	    CDEV_WRITE, PM_GRANT_TEST, SYS_GETINFO_NAME_LEN,
38	};
39	use minixrs_kernel_shared::com::{PM_PROC_NR, TTY_PROC_NR, boot_endpoint};
40	use minixrs_kernel_shared::endpoint::Endpoint;
41	use minixrs_kernel_shared::error::{ENXIO, EPERM, OK};
42	use minixrs_kernel_shared::grant::{CPF_READ, CPF_WRITE};
43	use minixrs_server_rt::{
44	    GrantPool, SefConfig, diag_fmt, sef_publish_to_ds, sef_retrieve_from_ds, sef_startup, wr_i32,
45	    wr_u64,
46	};
47	
48	/// Bytes VFS grants PM in the slice-5.2 demo.
49	const GRANT_TEST_LEN: usize = 64;
50	
51	/// Number of simultaneously outstanding grants VFS can hold. VFS's stack is one
52	/// page, and the pool costs `N * 32` bytes; 8 is ample for the demo.
53	const GRANT_SLOTS: usize = 8;
54	
55	/// The granted buffer. A `static` (not `static mut`) so it lands in `.rodata`,
56	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant,
57	/// and it means the kernel's `Prot::writable` check would reject any attempt to
58	/// safecopy *into* it.
59	static GRANT_TEST_BUF: [u8; GRANT_TEST_LEN] = grant_test_pattern();
60	
61	/// A deterministic, non-trivial byte pattern. Deterministic so PM's checksum is
62	/// a fixed value across runs; non-trivial (not `i`, not a constant) so a copy
63	/// that lost or duplicated a chunk still changes the sum.
64	const fn grant_test_pattern() -> [u8; GRANT_TEST_LEN] {
65	    let mut b = [0u8; GRANT_TEST_LEN];
66	    let mut i = 0;
67	    while i < GRANT_TEST_LEN {
68	        b[i] = (i as u8).wrapping_mul(37).wrapping_add(11);
69	        i += 1;
70	    }
71	    b
72	}
73	
74	// ----- Slice 5.3: the CDEV console demo ------------------------------------
75	
76	/// The line VFS asks TTY to print. In `.rodata` (a `static`, not `static mut`),
77	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant.
78	static TTY_BANNER: [u8; 35] = *b"minix.rs vfs: hello via CDEV_WRITE\n";
79	
80	/// Length of the short-write probe: eight bytes past what one `CDEV_WRITE` can
81	/// carry, so the reply must come back clamped.
82	const TTY_RULE_LEN: usize = CDEV_MAX_IO + 8;
83	
84	/// A buffer deliberately longer than [`CDEV_MAX_IO`], whose byte at index
85	/// `CDEV_MAX_IO - 1` is `\n` — so the *clamped* write renders as exactly one
86	/// console line. The eight bytes past the clamp spell `TRUNCATE`, which therefore
87	/// must never appear on the console: if they do, the driver ignored its own limit.
88	static TTY_RULE: [u8; TTY_RULE_LEN] = tty_rule_pattern();
89	
90	const fn tty_rule_pattern() -> [u8; TTY_RULE_LEN] {
91	    let mut b = [b'-'; TTY_RULE_LEN];
92	    let prefix = b"minix.rs vfs: short-write rule ";
93	    let mut i = 0;
94	    while i < prefix.len() {
95	        b[i] = prefix[i];
96	        i += 1;
97	    }
98	    // Ends the line at the clamp boundary.
99	    b[CDEV_MAX_IO - 1] = b'\n';
100	    // Past the clamp: must never reach the console.
101	    let tail = b"TRUNCATE";
102	    let mut j = 0;
103	    while j < tail.len() {
104	        b[CDEV_MAX_IO + j] = tail[j];
105	        j += 1;
106	    }
107	    b
108	}
