110	/// ELF entry point. The kernel primes `SP_EL0` before `eret`, so `_start` can
111	/// dive straight into Rust without setting up a stack itself.
112	#[cfg(not(test))]
113	#[unsafe(no_mangle)]
114	#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
115	pub extern "C" fn _start() -> ! {
116	    main()
117	}
