119	#[cfg_attr(test, allow(dead_code))]
120	fn main() -> ! {
121	    // `sef_startup` learns VFS's endpoint/name and runs `vfs_init`, which
122	    // publishes VFS's endpoint to DS. The publish SENDREC blocks until DS is in
123	    // its receive loop — safe at boot (DS's init does no IPC). No signal
124	    // handling. On startup failure there is no recovery and nothing to print.
125	    let sef = sef_startup(SefConfig {
126	        init_fresh: Some(vfs_init),
127	        signal_handler: None,
128	    })
129	    .unwrap_or_else(|_| {
130	        loop {
131	            core::hint::spin_loop()
132	        }
133	    });
134	
135	    // The grant pool is a `main`-frame value that outlives the receive loop
136	    // below — it cannot live in `init_fresh`, whose frame is gone by the time a
137	    // grantee safecopies. (`server-rt` keeps the table as a value rather than a
138	    // static precisely so it can be owned like this.)
139	    let mut grants: GrantPool<GRANT_SLOTS> = GrantPool::new();
140	    grant_test(&mut grants);
141	    tty_demo(&mut grants);
142	
143	    let mut msg = Message {
144	        m_source: 0,
145	        m_type: 0,
146	        payload: [0u8; 96],
147	    };
148	    loop {
149	        // No file ops yet (Phase 5): receive and drop application traffic. The
150	        // SEF framework still services control traffic (pings/signals/re-init)
151	        // inside `receive`; only the application messages it hands back are
152	        // discarded here.
153	        let _ = sef.receive(&mut msg);
154	    }
155	}
