157	/// Slice 5.2 demo: direct-grant [`GRANT_TEST_BUF`] to PM and tell PM about it.
158	///
159	/// The grant id travels **in-band**, in the `PM_GRANT_TEST` payload, which is
160	/// how grant ids really travel — `CDEV_WRITE {minor, grant_id, len, offset}` has
161	/// the same shape, and takes its granter from `m_source` for the same reason. DS
162	/// could not carry one: `DS_PUBLISH` registers the kernel-stamped `m_source` and
163	/// ignores the payload, which is exactly its anti-spoof property.
164	///
165	/// `ipc_send` blocks until PM's receive loop picks the message up, so the demo
166	/// is self-synchronizing — no assumption is made about the two servers' SEF init
167	/// ordering. There is no cycle: VFS's own init only SENDRECs DS, and PM never
168	/// sends to VFS.
169	///
170	/// The buffer's raw address rides along too, so PM can read the same bytes a
171	/// second time with the ungranted `SYS_COPY` and compare.
172	///
173	/// A **second** grant over the same read-only buffer goes out claiming
174	/// `CPF_WRITE` — a granter lying about what its own memory permits. Nothing
175	/// stops a granter writing that entry, and the kernel copies through its own
176	/// HHDM alias where EL0 permission bits do not apply, so the only thing between
177	/// that lie and a corrupted `.rodata` page is the copy engine's explicit
178	/// `Prot::writable` check. PM probes it (`grant_denials`); this is the grant-path
179	/// analogue of slice 5.1's fourth bad-pointer probe.
180	///
181	/// Best-effort throughout: a failure here must not stop VFS from serving.
182	#[cfg_attr(test, allow(dead_code))]
183	fn grant_test(grants: &mut GrantPool<GRANT_SLOTS>) {
184	    let pm = boot_endpoint(PM_PROC_NR);
185	    let addr = (&raw const GRANT_TEST_BUF) as usize as u64;
186	    let len = GRANT_TEST_LEN as u64;
187	    let (Ok(gid), Ok(rw_gid)) = (
188	        grants.grant_direct(pm, addr, len, CPF_READ),
189	        grants.grant_direct(pm, addr, len, CPF_READ | CPF_WRITE),
190	    ) else {
191	        return;
192	    };
193	
194	    // No granter field: PM reads that off the kernel-stamped `m_source`, so
195	    // nothing in this payload can redirect PM's privileged copies at a third
196	    // party.
197	    let mut msg = Message {
198	        m_source: 0,
199	        m_type: PM_GRANT_TEST,
200	        payload: [0u8; 96],
201	    };
202	    msg.payload[0..4].copy_from_slice(&gid.to_ne_bytes());
203	    msg.payload[4..8].copy_from_slice(&(GRANT_TEST_LEN as i32).to_ne_bytes());
204	    msg.payload[8..12].copy_from_slice(&rw_gid.to_ne_bytes());
205	    msg.payload[16..24].copy_from_slice(&addr.to_ne_bytes());
206	    let _ = ipc_send(pm, &mut msg);
207	}
208	
209	/// Slice 5.3 demo: drive the TTY console driver over `CDEV_WRITE`.
210	///
211	/// VFS is the natural client — it is already the granter in the 5.2 demo, it
212	/// already owns a [`GrantPool`], and slice 5.4 puts its fd 1/2 on exactly this
213	/// path, so the wiring is not throwaway.
214	///
215	/// Four things get proven, in order:
216	///
217	/// 1. **DS lookup.** VFS asks DS for TTY's endpoint rather than hard-coding
218	///    `boot_endpoint(TTY_PROC_NR)`, which is what a real client does. On failure it
219	///    *does* fall back to the boot endpoint and says so — see [`tty_endpoint`].
220	/// 2. **A real write.** Grant the banner read-only to TTY, send `CDEV_WRITE`, and
221	///    check the reply equals the granted length. `match=1` rather than the length
222	///    itself: self-checking, and it does not have to be re-derived if the banner
223	///    text changes.
224	/// 3. **A short write.** Ask for `CDEV_MAX_IO + 8` bytes and require exactly
225	///    `CDEV_MAX_IO` back. This is the POSIX contract that lets a driver stage
226	///    through a small buffer, and it is the difference between "write returns a
227	///    count" and "write returns success".
228	/// 4. **Two denials.** Each request is valid in every respect but one, so removing
229	///    the corresponding check makes it *succeed* and turns the marker into a
230	///    `FAIL`. See [`cdev_denials`].
231	///
232	/// Best-effort throughout: a failure here must not stop VFS from serving.
233	#[cfg_attr(test, allow(dead_code))]
234	fn tty_demo(grants: &mut GrantPool<GRANT_SLOTS>) {
235	    let tty = tty_endpoint();
236	
237	    // 2. The banner, through a read-only direct grant.
238	    let banner_addr = (&raw const TTY_BANNER) as usize as u64;
239	    let banner_len = TTY_BANNER.len() as u64;
240	    let Ok(gid) = grants.grant_direct(tty, banner_addr, banner_len, CPF_READ) else {
241	        return diag_fmt(format_args!("cdev.write FAIL grant"));
242	    };
243	    let rc = cdev_write(tty, CDEV_MINOR_CONSOLE, gid, banner_len as i32, 0);
244	    if rc == banner_len as i32 {
245	        // The reply *is* the byte count, so equality with the granted length is
246	        // the whole assertion. A driver replying `OK` (0) fails this.
247	        diag_fmt(format_args!("cdev.write ok match=1"));
248	    } else {
249	        diag_fmt(format_args!("cdev.write FAIL rc={rc}"));
250	    }
251	    let _ = grants.revoke(gid);
252	
253	    // 3. The short write: more than one call can carry.
254	    let rule_addr = (&raw const TTY_RULE) as usize as u64;
255	    let Ok(rule_gid) = grants.grant_direct(tty, rule_addr, TTY_RULE_LEN as u64, CPF_READ) else {
256	        return diag_fmt(format_args!("cdev.short FAIL grant"));
257	    };
258	    let rc = cdev_write(tty, CDEV_MINOR_CONSOLE, rule_gid, TTY_RULE_LEN as i32, 0);
259	    if rc == CDEV_MAX_IO as i32 {
260	        diag_fmt(format_args!("cdev.short ok n={rc}"));
261	    } else {
262	        diag_fmt(format_args!("cdev.short FAIL rc={rc}"));
263	    }
264	    let _ = grants.revoke(rule_gid);
265	
266	    // 4. The requests that must be refused.
267	    cdev_denials(grants, tty, banner_addr, banner_len);
268	}
269	
270	/// Resolve TTY's endpoint through DS, falling back to its boot endpoint.
271	///
272	/// The lookup is the point — a client should not hard-code a peer's boot proc
273	/// number — but DS publish-before-retrieve is **not** guaranteed by construction.
274	/// It works today because `kernel/build.rs` packs TTY before VFS, so TTY's
275	/// `DS_PUBLISH` reaches DS's FIFO first and completes before VFS's own
276	/// `sef_startup` returns. Rather than let that archive ordering become load-bearing,
277	/// a failed lookup falls back to `boot_endpoint(TTY_PROC_NR)` and emits a
278	/// *distinguishable* diag line: the rest of the demo still runs and still proves the
279	/// CDEV path, while the required `cdev.ds ok` marker disappears and CI goes red on
280	/// the ordering regression specifically.
281	#[cfg_attr(test, allow(dead_code))]
282	fn tty_endpoint() -> Endpoint {
283	    let mut key = [0u8; SYS_GETINFO_NAME_LEN];
284	    key[0..3].copy_from_slice(b"tty");
285	    match sef_retrieve_from_ds(&key) {
286	        Ok(ep) => {
287	            diag_fmt(format_args!("cdev.ds ok ep={ep}"));
288	            ep
289	        }
290	        Err(rc) => {
291	            let ep = boot_endpoint(TTY_PROC_NR);
292	            diag_fmt(format_args!("cdev.ds FAIL rc={rc} fallback={ep}"));
293	            ep
294	        }
295	    }
296	}
297	
298	/// Probe the two `CDEV_WRITE` refusals that no successful write exercises.
299	///
300	/// Slice 5.1's lesson, again: a check no marker exercises is a check that can
301	/// regress silently. Each probe is well-formed in every respect but one.
302	///
303	///   - `bad-minor` — a perfectly good grant aimed at minor 7. The driver's own
304	///     minor check is the only thing that stops it, and the answer is `ENXIO`
305	///     because the *device* does not exist; nothing is wrong with the grant.
306	///   - `not-mine` — a grant over the same bytes, issued to **PM** instead of TTY.
307	///     TTY passes it to `SYS_SAFECOPY` in good faith and the *kernel* refuses it,
308	///     on `verify_grant`'s `who_to == caller's stored endpoint` check. `EPERM`,
309	///     and it is the check that makes a grant id safe to pass around at all: a
310	///     leaked id is useless to anyone but its named grantee.
311	#[cfg_attr(test, allow(dead_code))]
312	fn cdev_denials(grants: &mut GrantPool<GRANT_SLOTS>, tty: Endpoint, addr: u64, len: u64) {
313	    let (Ok(good), Ok(not_mine)) = (
314	        grants.grant_direct(tty, addr, len, CPF_READ),
315	        grants.grant_direct(boot_endpoint(PM_PROC_NR), addr, len, CPF_READ),
316	    ) else {
317	        return diag_fmt(format_args!("cdev.deny FAIL setup"));
318	    };
319	
320	    let probes: [(&str, i32, i32, i32); 2] = [
321	        ("bad-minor", 7, good, ENXIO),
322	        ("not-mine", CDEV_MINOR_CONSOLE, not_mine, EPERM),
323	    ];
324	
325	    let mut denied = 0usize;
326	    for (name, minor, gid, want) in probes {
327	        let rc = cdev_write(tty, minor, gid, len as i32, 0);
328	        if rc == want {
329	            denied += 1;
330	        } else {
331	            diag_fmt(format_args!("cdev.deny FAIL {name} rc={rc}"));
332	        }
333	    }
334	    if denied == probes.len() {
335	        diag_fmt(format_args!("cdev.deny ok n={denied}"));
336	    }
337	    let _ = grants.revoke(good);
338	    let _ = grants.revoke(not_mine);
339	}
340	
341	/// Issue one `CDEV_WRITE` to `tty` and return the reply `m_type` — the byte count
342	/// written, or a negative errno.
343	///
344	/// No granter goes in the payload: TTY takes it from the kernel-stamped `m_source`,
345	/// so this message cannot aim TTY's privileged `SYS_SAFECOPY` anywhere but VFS's own
346	/// address space.
347	#[cfg_attr(test, allow(dead_code))]
348	fn cdev_write(tty: Endpoint, minor: i32, gid: i32, len: i32, offset: u64) -> i32 {
349	    let mut m = Message {
350	        m_source: 0,
351	        m_type: CDEV_WRITE,
352	        payload: [0u8; 96],
353	    };
354	    wr_i32(&mut m, CDEV_MINOR_OFF, minor);
355	    wr_i32(&mut m, CDEV_GRANT_OFF, gid);
356	    wr_i32(&mut m, CDEV_LEN_OFF, len);
357	    wr_u64(&mut m, CDEV_OFFSET_OFF, offset);
358	    let trap_rc = ipc_sendrec(tty, &mut m);
359	    if trap_rc != OK {
360	        return trap_rc;
361	    }
362	    m.m_type
363	}
