365	/// SEF fresh-init callback: publish VFS's endpoint to DS under its name. DS
366	/// registers the caller's kernel-stamped endpoint, so `_endpoint` from
367	/// `GET_WHOAMI` is not sent.
368	#[cfg_attr(test, allow(dead_code))]
369	fn vfs_init(_endpoint: Endpoint, name: &[u8; SYS_GETINFO_NAME_LEN]) -> i32 {
370	    sef_publish_to_ds(name)
371	}
