3	//! minix.rs `init` — PID 1, the first user process (slice 4.8).
4	//!
5	//! Unlike the demo stubs it replaces, `init` is a real boot module: it is packed
6	//! into the boot-image archive with its true proc number (`INIT_PROC_NR = 10`)
7	//! and loaded + made runnable by the ordinary boot loop
8	//! (`kernel/src/arch/aarch64/userland.rs`), not hand-released by PM. It runs as
9	//! an ordinary user process — the shared `USER_PRIV_ID` privilege (SENDREC to PM
10	//! only, no kernel calls) — so the whole process lifecycle flows through PM in
11	//! the POSIX shape (user → PM, never user → kernel).
12	//!
13	//! `init` is the live exercise for the Phase-4 process machinery that the
14	//! slice-4.6/4.7 stub E demonstrated: it forks a child, the child execs the
15	//! `worker` binary (which runs a few `PM_GETPID` round-trips then exits), and
16	//! the parent `wait`s
17	//! to reap the zombie before looping to fork again. Each cycle recycles the same
18	//! fork-pool slot with an advancing endpoint generation — observable in the boot
19	//! trace as `SYS_FORK` / `SYS_EXEC` / `SYS_EXIT` triples.
20	//!
21	//! Built as a freestanding aarch64 ELF (`userland/init/user.ld`). It uses
22	//! `minix-ipc` directly — no `server-rt`/SEF, because it is a plain user program,
23	//! not a server. The `_start` shim and panic handler are gated to `not(test)`.
24	
25	#![cfg_attr(not(test), no_std)]
26	#![cfg_attr(not(test), no_main)]
27	
28	minixrs_abi_note::brand!();
29	
30	use minixrs_ipc::ipc_sendrec;
31	use minixrs_kernel_shared::Message;
32	use minixrs_kernel_shared::callnr::{PM_EXEC, PM_FORK, PM_WAIT};
33	use minixrs_kernel_shared::com::{PM_PROC_NR, boot_endpoint};
34	
35	/// The boot loader primes `SP_EL0` before `eret`, so `_start` can dive straight
36	/// into Rust without setting up a stack itself.
37	#[cfg(not(test))]
38	#[unsafe(no_mangle)]
39	#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
40	pub extern "C" fn _start() -> ! {
41	    main()
42	}
43	
44	/// Build a request message to PM: no payload, `m_source` is stamped by the kernel.
45	#[cfg_attr(test, allow(dead_code))]
46	fn pm_msg(m_type: i32) -> Message {
47	    Message {
48	        m_source: 0,
49	        m_type,
50	        payload: [0u8; 96],
51	    }
52	}
53	
54	#[cfg_attr(test, allow(dead_code))]
55	fn main() -> ! {
56	    let pm = boot_endpoint(PM_PROC_NR);
57	
58	    loop {
59	        // fork(): PM replies to both halves of this SENDREC — the child sees
60	        // `m_type == 0`, the parent sees the child pid (`> 0`); a negative value
61	        // is an errno (e.g. `EAGAIN` when the fork table is full).
62	        let mut m = pm_msg(PM_FORK);
63	        let _ = ipc_sendrec(pm, &mut m);
64	
65	        match m.m_type {
66	            0 => {
67	                // Child: replace this image with the `worker` binary. PM issues
68	                // `SYS_EXEC` and the kernel resumes us at worker's `_start`, so
69	                // this SENDREC never returns on success.
70	                let mut e = pm_msg(PM_EXEC);
71	                let _ = ipc_sendrec(pm, &mut e);
72	                // Unreachable on success; park defensively if exec ever failed.
73	                loop {
74	                    core::hint::spin_loop()
75	                }
76	            }
77	            n if n > 0 => {
78	                // Parent: reap the child (blocks until it exits), then loop to
79	                // fork the next one.
80	                let mut w = pm_msg(PM_WAIT);
81	                let _ = ipc_sendrec(pm, &mut w);
82	            }
83	            _ => {
84	                // Transient fork failure (table full): back off briefly, retry.
85	                for _ in 0..1024 {
86	                    core::hint::spin_loop()
87	                }
88	            }
89	        }
90	    }
91	}
92	
93	// The freestanding panic handler; under `cargo test` std supplies its own.
94	#[cfg(not(test))]
95	#[panic_handler]
96	fn panic(_: &core::panic::PanicInfo) -> ! {
97	    loop {
98	        core::hint::spin_loop()
99	    }
100	}
