1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! `CDEV_WRITE` request parsing and validation — the driver's pure logic.
4	//!
5	//! Everything here is a total function over a [`Message`], so it carries the
6	//! crate's unit tests. The IPC round-trip and the volatile MMIO stores live in
7	//! `main.rs` and `pl011.rs` respectively, and are verified through the boot log.
8	//! Same split as `servers/ds`'s `registry.rs` / `main.rs`.
9	//!
10	//! ## Two things this module is careful about
11	//!
12	//! **The granter is not here.** [`parse_write`] reads only the four payload
13	//! fields; the granter comes from the kernel-stamped `m_source`, which the caller
14	//! passes straight to `SYS_SAFECOPY`. A granter *field* would make any
15	//! grant-holding driver a confused deputy, aiming a privileged cross-address-space
16	//! copy wherever its client pointed. There is deliberately no way to express one
17	//! through this API.
18	//!
19	//! **An over-long request is a short write, not an error.** [`validate_write`]
20	//! clamps to [`CDEV_MAX_IO`] and reports the clamped count; the client re-sends
21	//! with `offset` advanced. That is POSIX `write()`'s contract, and it is what lets
22	//! the driver stage through a fixed buffer in its `main` frame with no allocator.
23	
24	use minixrs_kernel_shared::Message;
25	use minixrs_kernel_shared::callnr::{
26	    CDEV_GRANT_OFF, CDEV_LEN_OFF, CDEV_MAX_IO, CDEV_MINOR_CONSOLE, CDEV_MINOR_OFF, CDEV_OFFSET_OFF,
27	};
28	use minixrs_kernel_shared::error::{EINVAL, ENXIO};
29	use minixrs_kernel_shared::grant::grant_valid;
30	use minixrs_server_rt::{rd_i32, rd_u64};
31	
32	/// A parsed `CDEV_WRITE` request. Field-for-field the payload, with no
33	/// interpretation applied — [`validate_write`] does that.
34	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
35	pub struct WriteRequest {
36	    /// Device minor. Only [`CDEV_MINOR_CONSOLE`] exists today.
37	    pub minor: i32,
38	    /// Grant id naming the client's source buffer. Must carry `CPF_READ` and name
39	    /// this driver as grantee — both checked by the kernel, not here.
40	    pub gid: i32,
41	    /// Bytes the client asked to write. May exceed [`CDEV_MAX_IO`].
42	    pub len: i32,
43	    /// Offset within the granted range to start at. Advanced by the client across
44	    /// a short-write loop; range-checked against the grant by the kernel.
45	    pub offset: u64,
46	}
47	
48	/// Read a `CDEV_WRITE` request out of a message payload.
49	///
50	/// Total: every field is a fixed-offset scalar read that cannot fail (`server-rt`'s
51	/// accessors return `0` for an out-of-range offset), so a malformed request becomes
52	/// an invalid *value* that [`validate_write`] rejects, never a panic.
53	pub fn parse_write(msg: &Message) -> WriteRequest {
54	    WriteRequest {
55	        minor: rd_i32(msg, CDEV_MINOR_OFF),
56	        gid: rd_i32(msg, CDEV_GRANT_OFF),
57	        len: rd_i32(msg, CDEV_LEN_OFF),
58	        offset: rd_u64(msg, CDEV_OFFSET_OFF),
59	    }
60	}
61	
62	/// Decide how many bytes to move for `req`, or which errno to reply.
63	///
64	/// `Ok(n)` means "copy `n` bytes and reply `n`" — including `Ok(0)`, which is a
65	/// legal zero-length write that needs no copy at all. `Err(e)` is a negative errno
66	/// for the reply.
67	///
68	/// The checks, in the order a driver should apply them:
69	///
70	/// 1. `minor != CDEV_MINOR_CONSOLE` → `ENXIO`. Slice 5.11's `/dev/null` and
71	///    `/dev/zero` become additional minors here.
72	/// 2. `len < 0` → `EINVAL`. A negative length would otherwise widen into a huge
73	///    `u64` byte count for the kernel copy.
74	/// 3. An invalid grant id → `EINVAL`. Cheap local reject of the one value that can
75	///    never name a grant (`GRANT_INVALID`, and anything else negative); the kernel
76	///    still re-validates index, sequence, access, and grantee.
77	/// 4. `len == 0` → `Ok(0)`, checked *after* the gid so a zero-length write with a
78	///    garbage grant is still reported as the error it is.
79	/// 5. Otherwise clamp to [`CDEV_MAX_IO`].
80	pub fn validate_write(req: WriteRequest) -> Result<usize, i32> {
81	    if req.minor != CDEV_MINOR_CONSOLE {
82	        return Err(ENXIO);
83	    }
84	    if req.len < 0 {
85	        return Err(EINVAL);
86	    }
87	    if !grant_valid(req.gid) {
88	        return Err(EINVAL);
89	    }
90	    let len = req.len as usize;
91	    if len > CDEV_MAX_IO {
92	        return Ok(CDEV_MAX_IO);
93	    }
94	    Ok(len)
95	}
96	
97	#[cfg(test)]
98	mod tests {
99	    use super::*;
100	    use minixrs_kernel_shared::grant::{GRANT_INVALID, grant_id};
101	    use minixrs_server_rt::{wr_i32, wr_u64};
102	
103	    /// Build a well-formed `CDEV_WRITE` payload. The `granter` is deliberately not
104	    /// a parameter — there is no field for it.
105	    fn request(minor: i32, gid: i32, len: i32, offset: u64) -> Message {
106	        let mut m = Message {
107	            m_source: 0,
108	            m_type: 0,
109	            payload: [0u8; 96],
110	        };
111	        wr_i32(&mut m, CDEV_MINOR_OFF, minor);
112	        wr_i32(&mut m, CDEV_GRANT_OFF, gid);
113	        wr_i32(&mut m, CDEV_LEN_OFF, len);
114	        wr_u64(&mut m, CDEV_OFFSET_OFF, offset);
115	        m
116	    }
117	
118	    const GOOD_GID: i32 = grant_id(3, 1);
119	
120	    #[test]
121	    fn parse_reads_every_field_from_its_own_offset() {
122	        // Four distinct values, so a swapped pair of offsets would fail.
123	        let m = request(0, GOOD_GID, 64, 4096);
124	        assert_eq!(
125	            parse_write(&m),
126	            WriteRequest {
127	                minor: 0,
128	                gid: GOOD_GID,
129	                len: 64,
130	                offset: 4096,
131	            }
132	        );
133	    }
134	
135	    #[test]
136	    fn parse_of_a_zeroed_payload_yields_a_rejectable_request() {
137	        // A client that sent nothing at all: minor 0 happens to be the console,
138	        // but grant id 0 has sequence 0 and index 0, and length 0 is a no-op. The
139	        // point is that nothing panics and nothing copies.
140	        let m = Message {
141	            m_source: 0,
142	            m_type: 0,
143	            payload: [0u8; 96],
144	        };
145	        let req = parse_write(&m);
146	        assert_eq!(req.len, 0);
147	        assert_eq!(validate_write(req), Ok(0));
148	    }
149	
150	    #[test]
151	    fn a_normal_write_passes_its_length_through() {
152	        for len in [1i32, 12, 64, CDEV_MAX_IO as i32 - 1, CDEV_MAX_IO as i32] {
153	            let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, len, 0));
154	            assert_eq!(validate_write(req), Ok(len as usize), "len {len}");
155	        }
156	    }
157	
158	    #[test]
159	    fn an_over_long_write_is_clamped_not_refused() {
160	        // The short-write contract: the driver moves what it can and *reports* it,
161	        // so the client can advance `offset` and come back. A refusal here would
162	        // make every write longer than 256 bytes impossible.
163	        for len in [
164	            CDEV_MAX_IO as i32 + 1,
165	            CDEV_MAX_IO as i32 * 2,
166	            4096,
167	            i32::MAX,
168	        ] {
169	            assert_eq!(
170	                validate_write(parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, len, 0))),
171	                Ok(CDEV_MAX_IO),
172	                "len {len}"
173	            );
174	        }
175	    }
176	
177	    #[test]
178	    fn a_zero_length_write_is_ok_not_an_error() {
179	        let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, 0, 0));
180	        assert_eq!(validate_write(req), Ok(0));
181	    }
182	
183	    #[test]
184	    fn an_unknown_minor_is_enxio() {
185	        for minor in [1i32, 7, -1, i32::MAX] {
186	            let req = parse_write(&request(minor, GOOD_GID, 16, 0));
187	            assert_eq!(validate_write(req), Err(ENXIO), "minor {minor}");
188	        }
189	    }
190	
191	    #[test]
192	    fn a_negative_length_is_einval() {
193	        // Left unchecked this would widen into a ~16 EiB `u64` byte count for the
194	        // kernel copy call.
195	        for len in [-1i32, -256, i32::MIN] {
196	            let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, len, 0));
197	            assert_eq!(validate_write(req), Err(EINVAL), "len {len}");
198	        }
199	    }
200	
201	    #[test]
202	    fn an_invalid_grant_id_is_einval() {
203	        for gid in [GRANT_INVALID, -2, i32::MIN] {
204	            let req = parse_write(&request(CDEV_MINOR_CONSOLE, gid, 16, 0));
205	            assert_eq!(validate_write(req), Err(EINVAL), "gid {gid}");
206	        }
207	    }
208	
209	    /// Check order matters: a request that is wrong in two ways must report the
210	    /// *first* problem, so a client fixing one error learns about the next.
211	    #[test]
212	    fn the_minor_check_precedes_the_length_and_grant_checks() {
213	        let req = parse_write(&request(9, GRANT_INVALID, -5, 0));
214	        assert_eq!(validate_write(req), Err(ENXIO));
215	
216	        // ...and a bad grant is reported even on a zero-length write, rather than
217	        // being masked by the `Ok(0)` fast path.
218	        let req = parse_write(&request(CDEV_MINOR_CONSOLE, GRANT_INVALID, 0, 0));
219	        assert_eq!(validate_write(req), Err(EINVAL));
220	    }
221	
222	    /// The offset is passed through untouched: range-checking it is the kernel's
223	    /// job (`verify_grant` tests `offset + bytes <= grant.len`), and clamping or
224	    /// rejecting it here would break the short-write loop the client drives with it.
225	    #[test]
226	    fn the_offset_is_passed_through_unvalidated() {
227	        for offset in [0u64, 1, 256, u64::MAX] {
228	            let req = parse_write(&request(CDEV_MINOR_CONSOLE, GOOD_GID, 16, offset));
229	            assert_eq!(req.offset, offset);
230	            assert_eq!(validate_write(req), Ok(16));
