50	/// A server's grant table plus the bookkeeping the kernel does not keep.
51	///
52	/// `N` is the number of simultaneously outstanding grants the server can hold.
53	/// Slots are reused as grants are revoked; each reuse bumps the sequence
54	/// number, so an id for a revoked grant can never reach the slot's new
55	/// occupant.
56	pub struct GrantPool<const N: usize> {
57	    /// The table itself — this is the memory the kernel reads entries from, so
58	    /// its address is what `SYS_SETGRANT` registers.
59	    entries: [GrantEntry; N],
60	    /// Sequence number for the next allocation. Wraps at [`GRANT_MAX_SEQ`].
61	    next_seq: u32,
62	    /// Address last registered with the kernel; 0 before the first
63	    /// registration. Compared against the pool's live address so a moved pool
64	    /// re-registers rather than leaving the kernel pointed at stale memory.
65	    registered_at: usize,
66	}
67	
68	impl<const N: usize> Default for GrantPool<N> {
69	    fn default() -> Self {
70	        Self::new()
71	    }
72	}
73	
74	impl<const N: usize> GrantPool<N> {
75	    /// An empty pool. Nothing is registered with the kernel until the first
76	    /// grant is issued — a server that never grants pays no kernel call.
77	    pub const fn new() -> Self {
78	        Self {
79	            entries: [GrantEntry::EMPTY; N],
80	            next_seq: 0,
81	            registered_at: 0,
82	        }
83	    }
84	
85	    /// Grant `who_to` access to `[addr, addr + len)` **in this process's own
86	    /// address space**.
87	    ///
88	    /// `access` is `CPF_READ`, `CPF_WRITE`, or both. Returns the grant id to
89	    /// hand the grantee, or `EINVAL` for a malformed request / `ENOMEM` when
90	    /// every slot is in use. A failed `SYS_SETGRANT` is returned verbatim.
91	    pub fn grant_direct(
92	        &mut self,
93	        who_to: Endpoint,
94	        addr: u64,
95	        len: u64,
96	        access: u32,
97	    ) -> Result<i32, i32> {
98	        self.issue(CPF_DIRECT | access, who_to, NONE, addr, len)
99	    }
100	
101	    /// Grant `who_to` access to `[addr, addr + len)` in **`who_from`'s** address
102	    /// space — the third-party (magic) form.
103	    ///
104	    /// The kernel additionally requires this process to hold server-grade
105	    /// privilege, so a magic grant from an ordinary process is rejected at
106	    /// safecopy time with `EPERM`.
107	    pub fn grant_magic(
108	        &mut self,
109	        who_to: Endpoint,
110	        who_from: Endpoint,
111	        addr: u64,
112	        len: u64,
113	        access: u32,
114	    ) -> Result<i32, i32> {
115	        self.issue(CPF_MAGIC | access, who_to, who_from, addr, len)
116	    }
117	
118	    /// Revoke `gid`, freeing its slot for reuse.
119	    ///
120	    /// No separate kernel call announces this: the kernel re-reads the entry on
121	    /// every safecopy, so clearing the slot *is* the revocation. `EINVAL` if
122	    /// `gid` does not name a live grant of this pool (already revoked, wrong
123	    /// sequence, out of range).
124	    ///
125	    /// That is also exactly why this re-registers first. Clearing the slot only
126	    /// revokes anything if the kernel is reading *this* copy of the table — a
127	    /// pool that moved since its last registration would have its entry cleared
128	    /// here while the kernel kept honouring the stale address. A revocation that
129	    /// silently fails to take effect is the worst failure mode this type has, so
130	    /// it pays the address comparison (and, only if it actually moved, one
131	    /// `SYS_SETGRANT`) before touching the slot.
132	    pub fn revoke(&mut self, gid: i32) -> Result<(), i32> {
133	        if self.registered_at == 0 {
134	            // Nothing was ever granted, so nothing can be revoked — and a pool
135	            // that never granted still makes no kernel calls, as `new` promises.
136	            return Err(EINVAL);
137	        }
138	        self.ensure_registered()?;
139	        revoke_in(&mut self.entries, gid)
140	    }
141	
142	    /// Number of slots currently holding a live grant. Useful to a server that
143	    /// wants to fail early rather than discover `ENOMEM` mid-request.
144	    pub fn used(&self) -> usize {
145	        used_in(&self.entries)
146	    }
147	
148	    /// Register the pool with the kernel if its address has changed (or it was
149	    /// never registered). The only part of this module that traps.
150	    fn ensure_registered(&mut self) -> Result<(), i32> {
151	        let addr = (&raw const self.entries) as usize;
152	        if addr == self.registered_at {
153	            return Ok(());
154	        }
155	        let rc = sys_setgrant(addr as u64, N as i32);
156	        if rc != OK {
157	            return Err(rc);
158	        }
159	        self.registered_at = addr;
160	        Ok(())
161	    }
162	
163	    /// Shared body of the two grant constructors: make sure the kernel knows
164	    /// where the table is, then claim a slot.
165	    fn issue(
166	        &mut self,
167	        flags: u32,
168	        who_to: Endpoint,
169	        who_from: Endpoint,
170	        addr: u64,
171	        len: u64,
172	    ) -> Result<i32, i32> {
173	        self.ensure_registered()?;
174	        alloc_grant_in(
175	            &mut self.entries,
176	            &mut self.next_seq,
177	            flags,
178	            who_to,
179	            who_from,
180	            addr,
181	            len,
182	        )
183	    }
184	}
185	
186	/// Claim the first free slot and write a grant into it. Returns the packed id.
187	///
188	/// Rejects a malformed request up front (`EINVAL`): a zero-length or NULL
189	/// range, a range that overflows, or flags naming no access right — each of
190	/// which would produce a grant the kernel can only ever refuse, at a moment far
191	/// from the mistake.
192	#[allow(clippy::too_many_arguments)] // the fields of one grant entry, minus the
193	// sequence the helper assigns itself; bundling them into a struct would only be
194	// destructured here.
195	fn alloc_grant_in(
196	    entries: &mut [GrantEntry],
197	    next_seq: &mut u32,
198	    flags: u32,
199	    who_to: Endpoint,
200	    who_from: Endpoint,
201	    addr: u64,
202	    len: u64,
203	) -> Result<i32, i32> {
204	    if addr == 0 || len == 0 {
205	        return Err(EINVAL);
206	    }
207	    if addr.checked_add(len).is_none() {
208	        return Err(EINVAL);
209	    }
210	    if flags & CPF_ACCESS_MASK == 0 {
211	        return Err(EINVAL);
212	    }
213	    let Some(idx) = entries.iter().position(|e| e.flags & CPF_USED == 0) else {
214	        return Err(ENOMEM);
215	    };
216	
217	    let seq = *next_seq;
218	    *next_seq = (*next_seq + 1) & GRANT_MAX_SEQ;
219	    entries[idx] = GrantEntry {
220	        flags: flags | CPF_USED | CPF_VALID,
221	        seq,
222	        who_to,
223	        who_from,
224	        addr,
225	        len,
226	    };
227	    Ok(grant_id(idx as u32, seq))
228	}
229	
230	/// Clear the slot `gid` names, after checking that the id actually matches the
231	/// grant living there. Zeroing the whole entry is what makes the slot free
232	/// (`CPF_USED` clear) and simultaneously invalidates the id.
233	fn revoke_in(entries: &mut [GrantEntry], gid: i32) -> Result<(), i32> {
234	    if !grant_valid(gid) {
235	        return Err(EINVAL);
236	    }
237	    let Some(e) = entries.get_mut(grant_idx(gid) as usize) else {
238	        return Err(EINVAL);
239	    };
240	    if e.flags & CPF_USED == 0 || e.seq != grant_seq(gid) {
241	        return Err(EINVAL);
242	    }
243	    *e = GrantEntry::EMPTY;
244	    Ok(())
245	}
246	
247	/// Count the live grants in a table.
248	fn used_in(entries: &[GrantEntry]) -> usize {
249	    entries.iter().filter(|e| e.flags & CPF_USED != 0).count()
250	}
251	
252	/// Issue one `SYS_SETGRANT` naming `addr` as this process's grant table.
253	///
254	/// Returns the IPC trap's error if the SENDREC itself failed, else the kernel's
255	/// reply `m_type` — the two-step check every `server-rt` kernel-call helper
256	/// uses, since a trap-level failure and a call-level failure arrive by
257	/// different routes.
258	fn sys_setgrant(addr: u64, entries: i32) -> i32 {
259	    let mut msg = Message {
260	        m_source: 0,
261	        m_type: SYS_SETGRANT,
262	        payload: [0u8; 96],
263	    };
264	    msg.payload[4..8].copy_from_slice(&entries.to_ne_bytes());
265	    msg.payload[16..24].copy_from_slice(&addr.to_ne_bytes());
266	
267	    let trap_rc = ipc_sendrec(boot_endpoint(SYSTEM), &mut msg);
268	    if trap_rc != OK {
269	        return trap_rc;
270	    }
271	    msg.m_type
272	}
